ALTER TABLE audit_events
  DROP CONSTRAINT audit_events_action_v7,
  DROP CONSTRAINT audit_events_entity_v6,
  DROP CONSTRAINT audit_events_operation_v8,
  DROP CONSTRAINT audit_events_action_operation_v8,
  ADD CONSTRAINT audit_events_action_v8 CHECK (action IN ('employee.create', 'employee.update', 'employee.delete', 'account.manage', 'overtime.createSelfDraft', 'overtime.updateSelfDraft', 'overtime.deleteSelfDraft', 'overtime.submitSelf', 'overtime.manage', 'payroll.manage', 'supplemental.manage', 'finance.execute', 'finance.manage', 'reimbursement.createSelfDraft', 'reimbursement.updateSelfDraft', 'reimbursement.submitSelf')),
  ADD CONSTRAINT audit_events_entity_v7 CHECK (entity IN ('employee', 'overtime', 'payrollPlan', 'supplementalPayroll', 'financePosting', 'financeTransaction', 'financeRequest') AND CASE action WHEN 'employee.create' THEN entity = 'employee' WHEN 'employee.update' THEN entity = 'employee' WHEN 'employee.delete' THEN entity = 'employee' WHEN 'account.manage' THEN entity = 'employee' WHEN 'overtime.createSelfDraft' THEN entity = 'overtime' WHEN 'overtime.updateSelfDraft' THEN entity = 'overtime' WHEN 'overtime.deleteSelfDraft' THEN entity = 'overtime' WHEN 'overtime.submitSelf' THEN entity = 'overtime' WHEN 'overtime.manage' THEN entity = 'overtime' WHEN 'payroll.manage' THEN entity = 'payrollPlan' WHEN 'supplemental.manage' THEN entity = 'supplementalPayroll' WHEN 'finance.execute' THEN entity IN ('financePosting', 'financeRequest', 'financeTransaction') WHEN 'finance.manage' THEN entity IN ('financeTransaction', 'financeRequest') WHEN 'reimbursement.createSelfDraft' THEN entity = 'financeRequest' WHEN 'reimbursement.updateSelfDraft' THEN entity = 'financeRequest' WHEN 'reimbursement.submitSelf' THEN entity = 'financeRequest' ELSE FALSE END),
  ADD CONSTRAINT audit_events_operation_v9 CHECK (operation IN ('provision', 'reissue', 'disable', 'enable', 'submit', 'review', 'reject', 'approve', 'create', 'recalculate', 'return', 'cancel', 'commit', 'post', 'execute', 'void', 'update', 'pay')),
  ADD CONSTRAINT audit_events_action_operation_v9 CHECK (CASE action WHEN 'account.manage' THEN operation IS NOT NULL AND operation IN ('provision', 'reissue', 'disable', 'enable') WHEN 'overtime.submitSelf' THEN operation IS NOT NULL AND operation = 'submit' WHEN 'overtime.manage' THEN operation IS NOT NULL AND operation IN ('review', 'reject', 'approve') WHEN 'payroll.manage' THEN operation IS NOT NULL AND operation IN ('create', 'recalculate', 'review', 'approve', 'return', 'cancel', 'commit', 'post') WHEN 'supplemental.manage' THEN operation IS NOT NULL AND operation IN ('create', 'recalculate', 'review', 'approve', 'return', 'cancel', 'commit', 'post') WHEN 'finance.execute' THEN operation IS NOT NULL AND ((entity = 'financePosting' AND operation = 'execute') OR (entity = 'financeRequest' AND operation = 'pay') OR (entity = 'financeTransaction' AND operation = 'create')) WHEN 'finance.manage' THEN operation IS NOT NULL AND ((entity = 'financeTransaction' AND operation IN ('create', 'void')) OR (entity = 'financeRequest' AND operation IN ('create', 'update', 'submit', 'approve', 'reject', 'cancel'))) WHEN 'reimbursement.submitSelf' THEN operation IS NOT NULL AND entity = 'financeRequest' AND operation = 'submit' ELSE operation IS NULL END);
